    const metaByGame = {
      2048: ["数字益智", "键盘 · 滑动"],
      Blockrain: ["经典消除", "键盘 · 触控"],
      Gomoku: ["双人对弈", "实时联机"],
      DrawGuess: ["聚会互动", "2–8 人联机"]
    };
    component.itemSpacing = 0;
    component.primaryAxisAlignItems = "MIN";
    component.counterAxisAlignItems = "MIN";
    setRadius(component, 24, null);
